环形区间（猴子交友）
int dfs(int l,int r){
    if(l==r) return dp[l][r]=0;
    if(dp[l][r]!=0) return dp[l][r];
    dp[l][r]=INF;
    for(int k=l;k<=r;k++){
        dp[l][r]=min(dp[l][r],dfs(l,k)+dfs(k+1,r)+s[r]-s[l-1]);
    }
    return dp[l][r];
}

