int dfs(int pos,int last,int tight){
    if(pos==n) return 1;
    if(dp[pos][last][tight]!=-1) return dp[pos][last][tight];
    int limit=9;
    if(tight==1) limit=aint[pos];
    int ans=0;
    for(int i=0;i<=limit;i++){
        int nlast=0,ntight=0;
        if(i==2 && last==1) continue; 
        if(i==6) nlast=1;
        if(tight==1 && i==limit) ntight=1;
        ans+=dfs(pos+1,nlast,ntight);
    }
    return dp[pos][last][tight]=ans;
}

