int dfs(int pos,int pcnt,int tight,int start){
    if(pcnt>k) return 0;
    if(pos==n){
        if(start==0) return k==1;
        else return pcnt==k;
    }
    if(dp[pos][pcnt][tight][start]!=-1) return dp[pos][pcnt][tight][start];
    int limit=9;
    if(tight==1) limit=aint[pos];
    int ans=0;
    for(int i=0;i<=limit;i++){
        int npcnt=pcnt,ntight=0,nstart=start;
        if(start==0 && i!=0) nstart=1;
        if(nstart==1 && i==0) npcnt++;
        if(tight==1 && i==limit) ntight=1;
        ans+=dfs(pos+1,npcnt,ntight,nstart);
    }
    return dp[pos][pcnt][tight][start]=ans;
}

特殊整数（每一位互不相同）
int dfs(int pos,int mask,int tight,int start){
    if(pos==n){
        if(start==0) return 0;
        else return 1;
    }
    if(dp[pos][mask][tight][start]!=-1) return dp[pos][mask][tight][start];
    int limit=9;
    if(tight==1) limit=aint[pos];
    int ans=0; 
    for(int i=0;i<=limit;i++){
        int nmask=mask,ntight=0,nstart=start;
        if(start==0 && i!=0) nstart=1;
        if(nstart==1){
            if(mask&(1<<i)) continue;
            else nmask=mask|(1<<i);
        } 
        if(tight==1 && i==limit) ntight=1;
        ans+=dfs(pos+1,nmask,ntight,nstart);
    }
    return dp[pos][mask][tight][start]=ans;
}

